INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4e6d9e14-4047bc93-h1', 'task_6e07de475d5a4e6d9e14-h1', 'model_a4d87d41253c4047bc93', 'Pronoia', 'NO', 0.55, '事实（冻结包行情，unadjusted）：T=2026-09-07 收盘 41.07，当日开 41.65、高 41.76、低 41.03，收于全天最低区，较 09-04 收盘 41.69 下跌约 1.49%，并基本吞没 09-04 阳线实体；中期自 08-12（38.70）至 09-04（41.69）仍为上行结构。事实（新闻）：公告编号 2026-036，行长助理王兴海因工作原因辞任，自 2026-09-07 生效，公告称与董事会无不同意见、无未履行完毕承诺（含增持承诺）、已完成交接，属中层高管变动，不含经营或财务异常信息；时间戳 2026-09-07T10:31:54+00:00，按 UTC 口径晚于 A 股当日收盘。推断：该公告对基本面与治理影响甚微，仅存极轻微负面情绪，且不构成 09-07 盘中走弱的解释；09-07「冲击前高（41.76/41.78 区域）后长阴收低、吞没前日阳线」属典型冲高受阻信号，短线动能偏负，故 T+1 收盘低于 41.07 的概率略高。不确定性：中期上行结构未破，41.03 及 40.86–41.07 一带存在支撑，若企稳反弹则方向反转；T 日跌幅或含无', 'NO', '2026-09-17T11:44:38.761134+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-42a1abae-4047bc93-h1', 'task_9603c072f71542a1abae-h1', 'model_a4d87d41253c4047bc93', 'Pronoia', 'NO', 0.58, '事实：T日(2026-09-07)收盘56.36，前一交易日(2026-09-04)收盘58.24，单日-3.23%；T日开58.24、高58.45、低56.18、收56.36，属平开低走并收于当日最低区，是典型弱势阴线。波段上8/14收51.75至9/4高点58.99（收58.24）累计约+12.5%，随后T日大幅回落。消息面：冻结包内仅一条公告——2026-09-07《关于选举第十三届董事会职工董事的公告》(临2026-028)，选举庄严女士为职工董事，任职尚待国家金融监督管理总局核准，属纯公司治理/程序性事项，不涉及经营、盈利、资本运作或股东行为，无可验证的增量基本面或资金流证据。推断：弱势阴线叠加前期涨幅偏大，短线动能与回吐压力偏空，T+1更可能延续调整而非立即反转向上；但唯一消息为中性的程序性公告，缺乏基本面催化与资金数据，存在单日大跌后超跌反抽的相反可能，故置信度低、接近随机。综合取DOWN，p_up=0.42。资料缺口：无T+1前的新增公告、无资金流与北向数据、无指数与板块环境数据。', 'NO', '2026-09-17T12:42:44.378893+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4fdda8cf-4047bc93-h1', 'task_9e8b7beeb8434fdda8cf-h1', 'model_a4d87d41253c4047bc93', 'Pronoia', 'YES', 0.54, '事实：T=2026-09-07中信证券收27.67元，较9/4的27.99元下跌1.14%，收在当日偏低区域；近期在27.04~28.05区间震荡，未创新低。9/7盘后公告董事会全票通过授权调整中信证券投资有限公司注册资本（上限200亿元、有效期36个月）。9/8盘前两条研报分别涉及锂价超跌反弹和OCS需求增长，对中信证券自身无直接现金流影响。推断：T日跌幅温和且仍处区间内，区间下沿附近存在均值回复可能；公告偏中性略正面，行业研报至多间接情绪扰动。综合为高不确定性下弱偏涨，置信度低。', 'NO', '2026-09-17T12:43:08.030112+00:00');
