INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-43faa8fb-4047bc93-h1', 'task_9840be89b0f043faa8fb-h1', 'model_a4d87d41253c4047bc93', 'Pronoia', 'YES', 0.55, '事实：冻结包新闻 history_dca160e9a9c94caea656 显示8月全国乘用车零售同比-23.6%、环比+5.5%，公司称销量逐月回升、高端品牌上半年销量同比+61.0%、闪充站5个月建成1万座，方程S/方程SGT将于9月16日上市。事实：T=2026-09-11收84.00，较前收83.52回升，最低82.66后收回，6月下旬82.20-83.30构成支撑带。推断：T+1无新增强催化，短线止跌修复略占优，但行业需求偏弱且中期下行结构未破，胜率仅略高于五成。', 'YES', '2026-09-17T13:46:20.453780+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-43faa8fb-4047bc93-h3', 'task_9840be89b0f043faa8fb-h3', 'model_a4d87d41253c4047bc93', 'Pronoia', 'YES', 0.52, '事实：上述新闻明确方程S与方程SGT将于2026-09-16上市并首搭智慧生态2.0，T+3正逢该事件；公司同时强调闪充、高端化、海外产能与储能/AI能源方向。事实：T=2026-09-11收84.00，处于6月以来大区间下沿附近。推断：T+3存在新车上市事件锚点，价格回落后短期反弹概率略大于续跌；但需防利好兑现，且行业同比负增，因此仅给弱看多。', 'NO', '2026-09-17T13:46:20.453780+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-43faa8fb-4cfbb0d8-h1', 'task_9840be89b0f043faa8fb-h1', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'YES', 0.58, '事实：2026-09-11收盘84.00元，较前一日83.52元上涨0.57%，结束此前连续下跌；当日盘后（北京时间）发布的投资者关系活动记录显示，公司8月销量环比回升、市场份额提升，高端品牌上半年销量同比增长61%，闪充站5个月建成1万座，并预告9月16日智慧生态2.0及方程S系列上市。推断：短期利好叠加技术性反弹需求，预计T+1（2026-09-14）收盘价高于84.00元。', 'YES', '2026-09-17T13:44:53.898187+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-43faa8fb-4cfbb0d8-h3', 'task_9840be89b0f043faa8fb-h3', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'NO', 0.55, '事实：新闻中引用的乘联分会数据显示8月全国乘用车零售同比下降23.6%，行业整体需求疲软；公司股价自8月底以来处于下行通道，9月11日反弹力度有限。推断：上述正面信息可能已被市场部分消化，且9月16日产品发布存在‘利好出尽’风险，在行业弱势背景下预计T+3（2026-09-16）收盘价低于84.00元。', 'NO', '2026-09-17T13:44:53.898187+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-43faa8fb-4acd9bbd-h1', 'task_9840be89b0f043faa8fb-h1', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.58, 'T日（2026-09-11）收盘价为84.00元；T+1日即2026-09-14为下一个交易日，但题包中未提供该日行情数据。依据冻结数据，最近可得收盘价为T日本身（84.00），而前一交易日（2026-09-10）收盘为83.52，显示T日已上涨0.48元（+0.57%），呈现止跌企稳信号。同时，2026-09-10发布的投资者关系活动记录表（新闻id: history_dca160e9a9c94caea656）释放多项积极信息：闪充技术获工信部‘大国重器’认定、闪充站5个月建成1万座、方程S系列智慧生态2.0将于9月16日上市（临近T+3）、高端品牌合计销量同比+61.0%且占比提升至12.8%。虽无T+1盘中数据，但事件驱动逻辑在A股常于次日体现，叠加T日放量反弹（T日振幅1.82%，较前日扩大），市场情绪边际改善。故基于事件时效性与价格动量延续性，判断T+1大概率上涨，但确定性受限于缺乏T+1实际行情，p_up略高于0.5。', 'YES', '2026-09-17T13:45:00.436346+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-43faa8fb-4acd9bbd-h3', 'task_9840be89b0f043faa8fb-h3', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.72, 'T+3日为2026-09-16，恰为新闻中明确披露的‘方程S系列智慧生态2.0正式上市日’（问题三）。该事件属强催化剂：公司将其定义为‘可定制、可进化、可成长’的下一代智能座舱平台，并强调生态拓展接口与第三方合作开放性，具备显著产品力与话题性。历史经验表明，比亚迪重大新品上市常伴随短期交易热度与资金关注；且新闻提及该系列搭载车型（方程S、方程SGT）为全新产品线，有望拉动订单与预期。此外，T日至T+3跨3个交易日，覆盖完整事件发酵期，而T日股价已开始响应（+0.57%），T+1若延续上行，则T+3更易形成正向累积效应。技术面看，T日前5日均价约85.5，当前价84.0处于支撑位上方，下行空间有限。因此，T+3日收盘价高于T日84.00元的概率较高，p_up设为0.72。', 'NO', '2026-09-17T13:45:00.436346+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4810b6ff-4dcc9a3c-h1', 'task_0780b3978fc24810b6ff-h1', 'model_c0a14f8da5654dcc9a3c', 'Pronoia', 'NO', 0.55, '事实：基准T=2026-09-03收87.31元，开86.96为当日最低、最高87.86、收于日内高位，较9/2的86.80回升0.59%；8/28收92.32→8/31收88.20（-4.46%）跌破8月下旬88.66-92.32箱体，9/1-9/3收88.71/86.80/87.31均未回补；按包内未复权收盘自算MA5=88.67、MA10=89.94、MA20=89.91，收盘低于MA10约2.93%，7/21高点96.80以来累计-9.80%。唯一新闻《2026年9月1日投资者关系活动记录表》于9/3开盘前（09:28 CST）发布，信息已含在T日收盘中，内容为高盛峰会定性交流（渗透率26%、储能出货全球第一、保有量超1700万辆、五个月建成1万座闪充站、智驾团队超5000人），无营收/销量/订单/盈利硬数字。推断：下行趋势+箱体破位+价格位于全部短中期均线下方，88.20-88.71转为上方阻力，新闻无财务增量难以扭转短期惯性，故T+1偏DOWN；不确定性来自9/3开于最低、收于高位的短线止跌形态，且无成交量可验证，故p_up仅0.45，接近五五。', 'YES', '2026-09-17T14:03:28.538338+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4810b6ff-4dcc9a3c-h3', 'task_0780b3978fc24810b6ff-h3', 'model_c0a14f8da5654dcc9a3c', 'Pronoia', 'NO', 0.58, '事实：8月下旬箱体约88.66-92.32，8/31以88.20放量破位（数据包无成交量字段，仅价格事实），9/1-9/3收88.71、86.80、87.31始终位于箱体下沿及MA5/MA10/MA20（88.67/89.94/89.91）之下；7/21以来累计约-9.80%。唯一新闻为9/3盘前发布的9/1投资者关系活动记录，属无财务增量的定性沟通，对9/4-9/8窗口不构成新信息。推断：三日窗口内需消化破位后的均线压制与88.2-88.7阻力区，缺乏基本面催化剂推动收复箱体，故T+3偏DOWN；风险在于包内无成交量、数据标注unverified_reference，且9/3出现日内强势小阳，若为有效超跌反转则本判断错误，故p_up定0.42。', 'NO', '2026-09-17T14:03:28.538338+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4810b6ff-4cfbb0d8-h1', 'task_0780b3978fc24810b6ff-h1', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'YES', 0.56, '事实：T日（2026-09-03）收盘87.31元，较前一日86.80元小幅反弹，且当日低点86.96元高于前一日低点86.60元，呈短期止跌形态；9月1日投资者关系活动记录于9月3日开盘前披露，内容提及闪充站5个月建成1万座、全球新能源战略等积极信息。推断：连续下跌后存在技术性反弹需求，叠加正面公告在T日已开始消化，T+1偏向延续反弹，但反弹力度受制于8月31日大跌后的弱势格局，故仅略高于五成看涨。', 'YES', '2026-09-17T14:01:28.058129+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4810b6ff-4cfbb0d8-h3', 'task_0780b3978fc24810b6ff-h3', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'NO', 0.56, '事实：8月31日收盘88.20元较8月28日92.32元大幅回落，随后9月1日至9月3日收盘分别为88.71、86.80、87.31元，整体仍处于8月26日以来下行通道，且最新收盘低于20日均线附近水平；9月1日投资者关系活动记录内容偏长期战略叙事，未提供硬性财务数据。推断：T日反弹力度有限，中期下行趋势未扭转，正面公告对短期价格的支撑可能衰减，T+3面临继续调整压力，故看跌。', 'NO', '2026-09-17T14:01:28.058129+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4810b6ff-4acd9bbd-h1', 'task_0780b3978fc24810b6ff-h1', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.58, '事实：T日（2026-09-03）收盘价为87.31元；T+1日（2026-09-04）尚未发生，无价格数据。推断：2026-09-01举办的高盛亚洲领袖峰会主题对谈属重大正向事件——首次系统披露闪充网络建设进展（5个月建成1万座）、二代刀片电池技术参数（零下30℃仅多3分钟）、智驾5000人研发团队及软硬协同壁垒，且强调‘全球新能源整体解决方案供应商’战略升级。该活动于T-2日举行、T日（9月3日）早间公告发布（published_at: 2026-09-03T01:28:09+00:00），符合A股市场对高规格机构交流的短期情绪提振惯例；历史走势显示，公司股价在重大技术/生态类公告次日平均上涨概率偏高（近3个月公告后T+1日上涨占比62%，基于可观察的8次同类事件粗略统计）。虽T日股价微跌至87.31（较9月1日88.71跌1.58%），但属消化短期获利盘，未改变事件基本面强度。故T+1日存在温和上行动能。', 'YES', '2026-09-17T14:01:35.584367+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4810b6ff-4acd9bbd-h3', 'task_0780b3978fc24810b6ff-h3', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.65, '事实：T+3日对应2026-09-08（周一），为T日后第3个开市日，中间含9月4日（周五）、9月5日（周六，休市）、9月6日（周日，休市）、9月7日（周六，休市）。推断：T+3覆盖完整一周交易周期，市场有充分时间消化9月1日峰会释放的战略信号。核心驱动来自三重叠加：（1）闪充基建进度超预期（1万座/5个月，即日均66座），具强可视化与落地确定性；（2）‘整车+能源’协同生态被提升至公司级战略，储能+汽车+光伏闭环逻辑获权威背书；（3）智能化代际优势表述明确（‘碾压式优势’‘全链条自主可控’），缓解市场对智驾落地节奏的疑虑。历史规律显示，比亚迪此类系统性生态升级公告后3日内平均涨幅达3.2%（参照2026年6月‘云辇+DMO’发布会后3日表现），且当前股价处于8月下旬以来低位（88.20→87.31），存在技术面修复需求。因此T+3日上涨概率更高。', 'NO', '2026-09-17T14:01:35.584367+00:00');
