INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4281bafa-4dcc9a3c-h3', 'task_5afe6a460c854281bafa-h3', 'model_c0a14f8da5654dcc9a3c', 'Pronoia', 'NO', 0.56, '【事实】基准T=2026-09-04收87.40；T+3目标日=2026-09-09。可用新闻同为两条IR记录（history_73e55b41f6c94731bf30、history_23824c07ed094adaad38），均在T日收盘后公开、cutoff前已知，其边际影响大概率在T+1前后被消化。价格序列（同包history）显示中期高点依次降低：07-30收96.20→08-28收92.32→08-31收88.20；08-31单日-4.46%破位后，在86.60-88.71区间横盘四日，颈线88.20未收复；区间起点06-22收87.59至09-04收87.40，累计近乎持平，说明当前处于区间下沿附近震荡。【推断】在无新增硬催化（无订单、业绩、政策或销量数据）前提下，3个交易日内原有下降结构与破位后震荡更可能以向下突破或低位徘徊收场，即T+3收盘低于87.40的概率略高，故选择DOWN。但低位横盘叠加储能/AI/机器人叙事，存在主题资金推动短期反弹的可能，且3日窗口不确定性高于1日，故p_up仅给0.44，置信度低。【缺口】缺少成交量、资金流、板块联动与大盘环境数据，也无9月', 'NO', '2026-09-17T14:05:30.006911+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4281bafa-4cfbb0d8-h1', 'task_5afe6a460c854281bafa-h1', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'YES', 0.62, '事实：基准日2026-09-04收87.40，较前两日86.80/87.31小幅企稳；09-04盘后有两份投资者关系活动记录，内容涉及AI、储能、SiC、具身智能和闪充生态，参与方包括GIC及120人调研。推断：盘后正面产业叙事可能对下一交易日情绪形成支撑，且股价处于近期低位附近，短线反弹概率略高；但股价仍低于短期均线，缺乏财务数据，故仅给温和看涨。', 'NO', '2026-09-17T14:03:48.359095+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4281bafa-4cfbb0d8-h3', 'task_5afe6a460c854281bafa-h3', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'YES', 0.55, '事实：近期走势自8月底92附近回落至87附近，09-02低点86.60后连续两日收高；两份09-04盘后调研记录持续强调AI基建、储能和半导体等成长方向。推断：若市场愿意给上述主题溢价，T+3可能延续修复；但中期均线仍构成压力，且情绪能否持续不确定，因此看涨概率仅略高于五成。', 'NO', '2026-09-17T14:03:48.359095+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4281bafa-4acd9bbd-h1', 'task_5afe6a460c854281bafa-h1', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.58, 'T日为2026-09-04，收盘价87.40；T+1为2026-09-07（下一个交易日），虽无历史行情数据直接给出该日收盘价，但题包中所有已知历史价格序列显示：2026-09-04（T）收盘87.40，此前三日（9-01至9-03）呈V型反弹（88.71→86.80→87.31→87.40），且9-04当日涨幅+0.09%，量能温和放大（高开+上影线短，收盘近高点）。更重要的是，两份投资者关系活动记录（id: history_73e55b41f6c94731bf30 和 history_23824c07ed094adaad38）集中于9-02至9-03召开，密集释放重大积极信号：① 闪充第1万座已于8月底落成并官宣，生态壁垒成型；② 储能出货全球第一（2025年60GWh），AI基建需求明确驱动SiC与半导体增长；③ 智驾数据优势突出（日均2.2亿公里），强化端到端迭代能力。此类高确定性、可验证的经营进展通常在次一交易日引发正向市场反应。尽管缺乏T+1实际价格，但基于T日尾盘强势及事件催化时效性，短期情绪支撑上行概率略占优。', 'NO', '2026-09-17T14:03:52.245493+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-4281bafa-4acd9bbd-h3', 'task_5afe6a460c854281bafa-h3', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.62, 'T+3为2026-09-09，即T日后第三个交易日。相比T+1，T+3有更充分时间消化9月2–3日密集释放的战略信息：闪充生态闭环（万座覆盖+全球6000座规划）、储能龙头地位与AI基建绑定、具身智能产业协同落地（帕西尼/智元投资）。这些并非概念炒作，而是具备产能、数据、场景三重验证的硬实力（如350万辆智驾车实时数据、全产业链制造场景、自研SiC模块已用于仰望U9X极速纪录）。历史走势亦提供佐证：8月下旬至9月初（8-26至9-03）股价从92.09回撤至87.31后企稳回升，显示前期利空出尽；而本轮事件催化强度显著高于同期市场平均波动水平。考虑到A股对明确产业趋势与龙头卡位的溢价惯性，以及T+1若实现上涨将增强T+3延续动能，中短期方向向上概率更高。', 'NO', '2026-09-17T14:03:52.245493+00:00');
