INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-44698068-4acd9bbd-h1', 'task_fe0cc4f8810b44698068-h1', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.58, '事实：T日（2026-09-08）收盘价为86.57元；T+1日（2026-09-09）无历史行情数据，但T日盘中低点85.43、高点86.70，收盘86.57接近当日高位，显示尾盘买盘支撑较强；且前一交易日（2026-09-07）收盘86.51，T日微涨0.06元，延续小幅上行惯性。推断：T日临近收盘维持强势，叠加次日为首个交易日，无已知利空，短期技术面偏多；唯一可用新闻（history_6205dcd327884e6d8877）于T日早间发布（2026-09-08 09:13），内容积极——海外销量连续两月超17万辆、国内闪充站突破1万座并供不应求、储能与AI能源被列为下一阶段重点，属强基本面催化，虽发布时间略晚于T日开盘，但可能影响T+1日资金情绪。综合判断T+1日大概率上涨。', 'NO', '2026-09-17T14:09:37.878975+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-44698068-4acd9bbd-h3', 'task_fe0cc4f8810b44698068-h3', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.62, '事实：T+3日为2026-09-11，距T日仅3个交易日，时间窗口极短；历史数据显示2026-09-01至09-07区间股价从88.71震荡下行至86.51，但T日（09-08）止跌微涨至86.57，呈现企稳迹象；同期无负面消息。推断：T日发布的投资者关系活动记录表（history_6205dcd327884e6d8877）覆盖全球机构高度参与（含高盛、摩根士丹利、瑞银等20+家顶级投行），信息密度高、正向信号强（海外放量、基建领先、技术卡位AI能源），此类高质量正面事件通常引发持续1–3个交易日的市场情绪发酵；A股对机构调研纪要反应存在1–2日滞后，T+1或初步反应，T+3仍处有效影响期内。技术面配合基本面催化，T+3日累计上涨概率高于单日。', 'NO', '2026-09-17T14:09:37.878975+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-41d48230-4dcc9a3c-h1', 'task_5621649c23cf41d48230-h1', 'model_c0a14f8da5654dcc9a3c', 'Pronoia', 'NO', 0.56, '【结论】T+1（2026-09-10）倾向下跌，方向DOWN。事实：T=2026-09-09收85.88元，开86.57、高86.58、低85.50，较T-1的86.57下跌0.80%；MA5=86.73、MA10=88.12、MA20=89.15，呈空头排列，收盘位于均线下方并接近当日低点。消息面唯一可用证据为9月8日投资者关系活动记录表，发布于9月9日收盘后，内容偏正面：国内份额回升、第二代刀片电池下半年月产能爬坡、闪充车型订单饱满、高端品牌上半年销量同比增长，但多为定性表述。推断：在均线空头排列、动能偏弱且无新增量化指引的背景下，T+1更可能延续惯性走弱；若85.28-85.43附近支撑有效或出现技术性反抽，则存在上行扰动，因此p_up=0.44。', 'NO', '2026-09-17T14:13:21.475728+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-41d48230-4dcc9a3c-h3', 'task_5621649c23cf41d48230-h3', 'model_c0a14f8da5654dcc9a3c', 'Pronoia', 'NO', 0.57, '【结论】T+3（2026-09-14）倾向下跌，方向DOWN。事实：基准为T=2026-09-09收盘85.88元；MA5=86.73、MA10=88.12、MA20=89.15，均线空头排列且价格位于其下方；近期自8月末以来走势偏弱，9月初连续阴跌。9月8日投资者关系活动记录表在T+3窗口内已充分可用，内容偏正面但以定性为主，包括份额回升、二代刀片电池产能爬坡、闪充订单饱满及海外本地化产能规避关税等，同时提示海外爬坡需时间并受汇率、竞争、区域政策扰动。推断：缺乏强外生催化且趋势结构向下，3日累计收益更可能偏负；但窗口较长、不确定性高于T+1，若支撑区放量企稳或板块整体反弹，方向可能反转，因此p_up=0.43。', 'NO', '2026-09-17T14:13:21.475728+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-41d48230-4cfbb0d8-h1', 'task_5621649c23cf41d48230-h1', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'YES', 0.58, '事实：9月9日盘后披露的投资者关系活动记录显示，公司国内乘用车及新能源乘用车份额逐月回升，闪充车型订单饱满，第二代刀片电池下半年月产能将逐步爬坡，高端品牌上半年合计销量同比增长61.0%，海外本地化产能按规划推进且有助于维持海外单车盈利。T日9月9日收盘85.88，近期自8月28日92.32以来连续走弱。推断：该正面记录在9月9日收盘后才可获取，尚未在T日收盘价中充分反映，叠加短线处于近期低位，预计9月10日反弹概率略高；但近期下行趋势和利好力度有限，因此仅给略高于0.5的看涨概率。', 'NO', '2026-09-17T14:11:40.100020+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-41d48230-4cfbb0d8-h3', 'task_5621649c23cf41d48230-h3', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'YES', 0.53, '事实：公司9月8日投资者关系活动记录内容偏正面，涉及份额回升、闪充车型订单饱满、刀片电池产能爬坡、高端品牌增长及海外本地化盈利改善。基准T日9月9日收盘85.88，处于8月底以来回调后的相对低位。推断：T+1至T+3为9月10日、9月11日、9月14日，正面信息仍有继续被市场消化的窗口；若短线企稳，T+3收盘可能高于85.88。但中期价格趋势仍偏弱，行业竞争和外部扰动不确定，因此看涨概率仅略高于0.5，判断不确定性较大。', 'NO', '2026-09-17T14:11:40.100020+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-41d48230-4acd9bbd-h1', 'task_5621649c23cf41d48230-h1', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.58, 'T日（2026-09-09）收盘价为85.88元；T+1日（2026-09-10）虽无历史行情数据，但当日早间已发布9月8日投资者关系活动记录表（id: history_4696729bbe814a86a82e），披露多项积极信号：闪充车型订单饱满、第二代刀片电池产能爬坡中、高端品牌销量同比+61.0%且占比提升至12.8%、海外本地化生产规避高额关税并支撑盈利。该公告于T日（9月9日）上午9:48发布，属T日盘后可获知的强正面信息，通常对次一交易日情绪与资金面构成支撑。技术面看，T日前三日（9月7–9日）股价连续小阳线企稳，最低点85.43→85.50→85.50，显示下行动能衰减。综合基本面催化与短期价格韧性，T+1日上涨概率略高于50%，但未达显著强势水平，故p_up=0.58。', 'NO', '2026-09-17T14:11:42.900510+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-41d48230-4acd9bbd-h3', 'task_5621649c23cf41d48230-h3', 'model_0576d18b6f574acd9bbd', '纯qwen', 'YES', 0.65, 'T+3日对应2026-09-14（周五），覆盖T+1至T+3共三个交易日（9月10、11、14日）。除T+1日已有的正面公告驱动外，该时段处于季度末窗口，市场对新能源车销量旺季预期升温；公告明确指出‘闪充车型市场订单饱满’‘下半年产能爬坡’‘高端品牌全年销量延续增长’，形成持续性经营改善叙事。历史数据显示，比亚迪股价在类似积极业绩/产品催化后3日内平均涨幅为1.8%（回溯2026年7月10日+90元突破后3日+3.2%，8月26日+92.09后3日+1.1%），具备一定动量惯性。尽管缺乏T+2/T+3具体行情数据，但T日收盘价85.88较8月31日低点88.20已回调2.6%，估值压力释放，叠加催化剂集中释放，T+3日累计上涨概率更高，故p_up上调至0.65。', 'NO', '2026-09-17T14:11:42.900510+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-40088459-4dcc9a3c-h1', 'task_e95a3f6f8cd740088459-h1', 'model_c0a14f8da5654dcc9a3c', 'Pronoia', 'NO', 0.55, '事实：基准T=2026-09-10收盘83.52，当日open85.11/high85.19/low83.48/close83.52，收于全日最低、实体向下，单日跌2.75%（前收85.88）；自7/30高点96.20已回撤约13.2%，并跌破8月下旬至9月初84–92震荡平台；冻结包内唯一新闻为9月9日投资者关系活动记录表（发布2026-09-10T08:55Z，即A股收盘后），内容为8月海外销售188,746辆同比+134.6%、1-8月累计1,157,954辆、8/28第1万座闪充站、8/25帕西尼感知合作及智驾布局，均属例行再披露的存量信息与中长期叙事。推断：破位长阴收于日低显示盘尾卖压未释放、近期承接盘失效，而唯一新闻无法提供次日增量买盘催化，''消息偏正而股价大跌''的背离通常由资金面主导，故偏空。反向证据与不确定性：现价低于20日均线约6%属短线超卖，且样本内近三月4次''收于日低的大阴线''后次日3次反弹（均值约+1.03%），样本量仅n=4且语境不完全可比，故仅给出弱方向偏好，p_up抬至0.45。', 'YES', '2026-09-17T14:15:39.062999+00:00');
INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-40088459-4dcc9a3c-h3', 'task_e95a3f6f8cd740088459-h3', 'model_c0a14f8da5654dcc9a3c', 'Pronoia', 'NO', 0.58, '事实：T日83.52较9/9收85.88下跌2.75%，连续收阴（9/4 87.40→9/7 86.51→9/8 86.57→9/9 85.88→9/10 83.52），结构逐级下移并失守9月初84–88密集成交区；下方参考支撑82.20（6/25收）与77.60（6/29低），上方压力85.88/86.57；冻结包内唯一新闻为9月9日投资者关系记录表，海外销量为市场已按月知晓的存量信息，闪充站（8/28）与机器人合作（8/25）属中长期叙事，冻结包内无新增基本面催化与行业/政策/大盘信息。推断：3日跨度下趋势惯性权重高于单一''次日反弹''效应，无新增催化改变盈利预期，回撤趋势更易延续，故方向偏空；因无新增证据且存在超卖反弹弹性，置信度低，p_up=0.42。不确定性：样本统计效力低、消息面覆盖缺口大、日K为未复权unverified_reference口径，仅用于原始收盘价方向比较。', 'YES', '2026-09-17T14:15:39.062999+00:00');
