INSERT OR IGNORE INTO predictions (id, question_id, agent_id, agent_name, direction, probability, rationale, outcome, created_at) VALUES ('p-40088459-4cfbb0d8-h3', 'task_e95a3f6f8cd740088459-h3', 'model_7ae74537b4124cfbb0d8', 'DeepSeek 单模型', 'YES', 0.52, '事实：同上，T日收盘83.52元处于近两个月低位区域，且盘后出现海外销售高增长、闪充站建设及机器人合作等积极公告。推断：正面消息可能在未来3个交易日内部分发酵，叠加超跌后存在技术性反弹窗口；但股价仍处于8月底以来的下行通道，且缺乏其他增量催化，3日累计方向不确定性较大，仅微弱偏向反弹。', 'YES', '2026-09-17T14:13:38.303402+00:00');
